#!/usr/bin/env python3
"""Transcribe visually reviewed regional tables; retain source hashes for audit."""
import json,hashlib,argparse
from pathlib import Path
R=Path(__file__).resolve().parents[2];parser=argparse.ArgumentParser();parser.add_argument('downloads',type=Path);D=parser.parse_args().downloads;old={t['id']:t for t in json.loads((R/'tolls-es.json').read_text())['tolls']}
def out(id,file,**data):
 path=D/file;assert hashlib.sha256(path.read_bytes()).hexdigest()==json.loads((R/'scripts/coverage/source-lock.json').read_text())[file], 'Source changed: re-review before import';d={'kind':'tariff-reference','complete':False,'checked':'2026-09-16','currency':'EUR','vehicle_class':'light','validFrom':'2026-01-01','validThrough':'2026-12-31','timeZone':'Europe/Madrid','source':old[id]['source'],'sha256':hashlib.sha256(path.read_bytes()).hexdigest(),**data};(R/'pricing-candidates'/(id[3:]+'-tariffs.json')).write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
def row(name,cents):return {'name':name,'tariff':{'baseCents':cents,'bands':[]}}
out('es-c32-castelldefels-vendrell','es-c32-castelldefels-vendrell.pdf',barriers=[row('Vallcarca troncal',842),row('Cubelles troncal',503),row('Cubelles acceso',269),row('Calafell acceso',79)],notes=['Category II general tariffs, four explicitly published barrier rows.','Discount programs are not assumed. Map directional accesses before route pricing.'])
out('es-supersur','es-supersur.pdf',ods=[{'from':a,'to':b,'tariff':{'baseCents':n,'bands':[]}} for a,b,n in [('Arrigorriaga','Bilbao Sur',120),('Arrigorriaga','Ortuella',185),('Arrigorriaga','Santurtzi',205),('Bilbao Este','Bilbao Sur',75),('Bilbao Este','Ortuella',150),('Bilbao Este','Santurtzi',185),('Bilbao Sur','Ortuella',75),('Bilbao Sur','Santurtzi',120)]],notes=['Published 2026 general light-vehicle table. No obsolete zero-price night exemption.','Entry/exit mapping and combined-AP68 recurrence eligibility remain separate.'])
out('es-ap636','es-ap8-gipuzkoa.pdf',sections=[row('Beasain–Ormaiztegi',42),row('Ormaiztegi–Zumarraga',82),row('Legazpi/Urretxu–Bergara',155)],conditionalJourneys=[{'from':'Legazpi/Urretxu','to':'Antzuola','cents':52,'requires':['payment:via-t'],'sourceNote':'Tarifa aplicable en caso de pago con telepeaje'}],notes=['The Antzuola gantries identify the partial journey; do not add 0.52 to the full Deskarga 1.55 charge.','General full traverse is 2.79 EUR, not a fee at the western AP-1 booth. Directional partial-journey mapping remains required.'])
out('es-vallvidrera','tunels-2026.pdf',sourcePdf='https://tunels.cat/wp-content/uploads/2025/12/Tunels_tarifes_2026.pdf',generalReference={'valleyCents':470,'peakCents':528,'peakWeekdays':[1,2,3,4,5],'peakMinutes':[[450,630],[1020,1260]],'holidayRate':'valley','requiresCalendar':'Operator-applicable 2026 working days / holidays'},notes=['Category II. The tariff is 4.70 on Saturdays, Sundays and holidays.','Do not treat all weekdays as working days without the applicable holiday calendar. No automatic ECOVIAT/VAO/frequency enrollment.'])
